update public.video_studio_projects
set style = '공식 규칙서 기반 게임 소개 + 실제 진행자 출연', updated_at = now()
where title = '시계탑에 흐른 피';

with official_copy(position,title,scene_type,script,image_prompt,is_short,short_title) as (values
  (0,'공식 소개로 시작','진행자 실사','‘시계탑에 흐른 피’는 5명에서 20명이 함께 즐기는 소셜 디덕션 게임입니다. 추리와 기만, 거짓과 논리로 선과 악을 가려냅니다.','원형으로 앉아 대화하는 플레이어들과 테이블 중앙의 공식 게임 구성물',true,'5명부터 20명까지 함께하는 추리 게임'),
  (1,'레이븐스우드 블러프의 사건','만화 컷씬','레이븐스우드 블러프의 마을 광장, 시계탑에서 이야기꾼이 숨진 채 발견됩니다. 마을 사람들 사이에 인간의 모습으로 숨어든 악마를 찾아야 합니다.','레이븐스우드 블러프 마을 광장과 시계탑, 공식 규칙서의 사건 배경을 설명하는 삽화',false,null),
  (2,'낮의 토론과 밤의 행동','진행자 실사','낮에는 모두가 대화하며 정보를 공유하고, 의심되는 사람을 지목해 투표합니다. 밤에는 모두 눈을 감고, 일부 캐릭터가 이야기꾼의 안내에 따라 능력을 사용합니다.','낮에 원형으로 토론하는 플레이어와 밤에 눈을 감고 있는 플레이어의 대비',true,'낮에는 토론, 밤에는 능력'),
  (3,'사망해도 대화는 계속','자료 화면','사망한 플레이어도 게임에서 빠지지 않습니다. 계속 대화하고 정보를 나누며, 자기 팀의 승리를 위해 끝까지 참여합니다.','마을 광장 보드 위 사망 표시 토큰과 계속 토론하는 플레이어',false,null),
  (4,'사망자의 마지막 투표','자료 화면','사망한 플레이어에게는 게임이 끝날 때까지 사용할 수 있는 투표 한 표가 남습니다. 어느 지목에 그 한 표를 사용할지도 중요한 선택입니다.','공식 마을 광장 보드와 사망자 투표 토큰 하나를 가까이 보여 주는 화면',true,'죽어도 한 표가 남는다'),
  (5,'모두가 다른 캐릭터','자료 화면','각 플레이어는 서로 다른 캐릭터를 맡고 고유한 능력을 가집니다. 능력은 처음에만 작동하거나, 매일 밤 작동하거나, 특정 조건에서 작동하기도 합니다.','이야기꾼 마도서 안에 배치된 여러 캐릭터 토큰과 능력표',true,'모두에게 서로 다른 능력이 있다'),
  (6,'취함과 중독','진행자 실사','취하거나 중독된 플레이어는 자신이 그런 상태라는 사실을 모를 수 있습니다. 능력은 정상처럼 진행되지만 실제 효과는 없고, 받은 정보는 맞을 수도 틀릴 수도 있습니다.','마도서 안 캐릭터 토큰 옆에 놓인 취함과 중독 알림 토큰',false,null),
  (7,'이야기꾼의 역할','자료 화면','이야기꾼은 게임을 진행하고, 밤에 플레이어를 깨워 정보를 전달하며 능력을 처리합니다. 정답을 정해 두는 사람이 아니라 규칙 안에서 흥미로운 이야기가 이어지도록 판단합니다.','공식 마도서를 확인하며 밤 순서를 진행하는 이야기꾼의 손',false,null),
  (8,'선과 악의 승리 조건','진행자 실사','선한 팀은 악마를 찾아 처형하면 승리합니다. 악한 팀은 악마를 숨기고 생존자를 줄여, 여행자를 제외한 생존자가 두 명만 남으면 승리합니다.','마을 광장 보드 위 악마 토큰과 처형 투표 결과를 설명하는 화면',true,'악마를 찾으면 선한 팀 승리'),
  (9,'보드라운지에서 플레이','자료 화면','대화와 추리, 서로 다른 능력이 만드는 ‘시계탑에 흐른 피’를 보드라운지에서 이야기꾼과 함께 경험해 보세요.','보드라운지 게임 테이블 위 마을 광장 보드와 캐릭터 토큰, 로고 공간',false,null)
)
update public.video_studio_scenes scene
set title=copy.title,scene_type=copy.scene_type,script=copy.script,image_prompt=copy.image_prompt,is_short=copy.is_short,short_title=copy.short_title,updated_at=now()
from official_copy copy
join public.video_studio_projects project on project.title='시계탑에 흐른 피'
where scene.project_id=project.id and scene.position=copy.position;
